mapper.select:
Select * from score as s join student_information as si on s.student_number=si.student_number


        AND s.student_name LIKE CONCAT('%',#{studentName},'%')


        AND s.student_number LIKE CONCAT('%',#{studentNumber},'%')


        AND si.classes = #{classes}


        AND si.grade = #{grade}


        AND si.major = #{major}


        AND si.college = #{college}
